// CSD_RATIONALE_BEGIN
// Basis: attempt 2 (best at 40.8%) used SafeRepetitionPenaltyStep(4.0) and
// CloseSpanWithinBudget at closeReserve=80. All additions in attempts 10-12
// regressed performance. Attempt 12 with a 25-step span guard + EOS rescue
// dropped to 28.6% — the EOS rescue caused double CloseSpanWithinBudget calls
// wasting budget, and 25 steps was too tight for legitimate longer spans.
//
// Analysis of the `!!!!!!!!` failure pattern:
//   The model generates comparison operators (==, >, !=) inside << >>, and the
//   parser accepts them (Python comparison operators). After `sides % 2 ==`, the
//   valid continuations include `!` (for `!=`). SafeRepetitionPenaltyStep(4.0)
//   eventually penalizes `!` but the logit may be very high in the first few
//   occurrences. A span-step guard catches persistent loops while keeping budget
//   for CloseSpanWithinBudget to roll back to the last complete prefix.
//
// Changes from attempt 2:
// 1. 35-step per-span guard (not 25): allows legitimate spans up to 35 tokens
//    while still catching the `!` repetition loop; no EOS rescue (which wasted
//    budget in attempt 12); spanSteps reset to 0 on span entry and close.
// 2. Guidance: removed `**`; added explicit prohibition of comparison/assignment
//    operators; emphasised integer division with `//` and `int()` usage.
//    "mode_G" (3 examples with no delimiters) may improve with stronger format emphasis.
// 3. All other mechanics identical to attempt 2 (best).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (span guard / remaining <= closeReserve — CloseSpanWithinBudget):
//     Postcondition: `insideOut ==> parser.IsValidPrefix(currentOut)`. Both the
//     closed path (ci=false, implication vacuous) and the still-open path
//     (postcondition directly gives validity) preserve the invariant. ✓
//
//   (outside span branch):
//     RenderedEndsWith triggers => currentConstrainedOut := [] satisfies
//     IsValidPrefix([]) by method precondition. Otherwise insideConstrainedOut
//     stays false (vacuous). ✓
//
//   (IsCompletePrefix branch — CloseConstrainedSpan):
//     Sets insideConstrainedOut := false; implication vacuously true. ✓
//
//   (constrained step, non-EOS — SafeRepetitionPenaltyStep + AppendConstrainedToken):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS.
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   (EOS from constrained step): we break without state change; invariant was
//     true on entry, still true. ✓
//
//   (final cleanup — CloseSpanWithinBudget): same as span guard above. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (span guard, s = steps_before, remaining = maxSteps - s):
//     CloseSpanWithinBudget(remaining): |cg| <= |generated| + remaining
//     <= |generatedPrefix| + s + (maxSteps - s) = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (outside branch): steps += 1; at most one token appended to generated. ✓
//
//   (IsCompletePrefix branch): steps += 1; CloseConstrainedSpan appends at
//     most one `>>`. |generated| <= |generatedPrefix| + steps. ✓
//
//   (constrained step, s = old steps, steps = s+1):
//     AppendConstrainedToken appends exactly 1 token.
//     |generated| <= |generatedPrefix| + s + 1 = |generatedPrefix| + steps. ✓
//
//   (constrained step, EOS): steps = s+1; generated unchanged.
//     |generated| <= |generatedPrefix| + s < |generatedPrefix| + steps. ✓
//
//   (final cleanup): same argument as span guard. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap EVERY intermediate symbolic expression in << >> delimiters as you work. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use ONLY: numbers, problem variables, +, -, *, /, //, %, (), int(). " +
  "Use // for integer (floor) division. Use int() to convert a non-integer to integer. " +
  "Use the exact variable names given in the problem — never substitute numbers for variables. " +
  "Do NOT write comparison operators (==, !=, >, <, >=, <=) inside << >>. " +
  "Do NOT write assignments (=) inside << >>. " +
  "Do NOT write if/else or conditional expressions inside << >>. " +
  "Keep each << >> span to a single complete arithmetic expression.");

var closeReserve: nat := 80;
var maxSpanSteps: nat := 35;
var spanSteps: nat := if insideConstrained then |currentConstrained| else 0;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && (remaining <= closeReserve || spanSteps >= maxSpanSteps) {
    // Budget running low OR span too long: force-close using dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
        spanSteps := 0;
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    spanSteps := 0;
  } else {
    // Constrained generation with repetition penalty to discourage !-repetition loops
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
    );
    steps := steps + 1;
    spanSteps := spanSteps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

